import sys
sys.setrecursionlimit(1 << 25)

INF = 10**18

# 线段树：维护区间最小值 (绩效分, 员工编号)
class SegmentTree:
    def __init__(self, arr):
        self.n = len(arr) - 1       # arr 从下标 1 开始
        self.tree = [(INF, 0)] * (self.n * 4)
        self.build(1, 1, self.n, arr)

    def build(self, idx, l, r, arr):
        if l == r:
            self.tree[idx] = arr[l]
            return
        mid = (l + r) // 2
        self.build(idx * 2, l, mid, arr)
        self.build(idx * 2 + 1, mid + 1, r, arr)
        self.tree[idx] = min(self.tree[idx * 2], self.tree[idx * 2 + 1])

    def update(self, idx, l, r, pos, val):
        if l == r:
            self.tree[idx] = val
            return
        mid = (l + r) // 2
        if pos <= mid:
            self.update(idx * 2, l, mid, pos, val)
        else:
            self.update(idx * 2 + 1, mid + 1, r, pos, val)
        self.tree[idx] = min(self.tree[idx * 2], self.tree[idx * 2 + 1])

    def query(self, idx, l, r, ql, qr):
        if ql <= l and r <= qr:
            return self.tree[idx]
        mid = (l + r) // 2
        res = (INF, 0)
        if ql <= mid:
            res = min(res, self.query(idx * 2, l, mid, ql, qr))
        if qr > mid:
            res = min(res, self.query(idx * 2 + 1, mid + 1, r, ql, qr))
        return res


# 求 DFS 序，将子树映射为连续区间
def dfs(u, parent, graph, dfn, out, order, timer):
    timer[0] += 1
    dfn[u] = timer[0]
    order[timer[0]] = u
    for v in graph[u]:
        if v != parent:
            dfs(v, u, graph, dfn, out, order, timer)
    out[u] = timer[0]


# 处理题目要求的功能
def solve(n, m, edges, ops):
    graph = [[] for _ in range(n + 1)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    dfn = [0] * (n + 1)
    out = [0] * (n + 1)
    order = [0] * (n + 1)
    timer = [0]

    dfs(1, 0, graph, dfn, out, order, timer)

    # 按 DFS 序建立初始数组
    arr = [None] * (n + 1)
    ans = [0] * (n + 1)
    for pos in range(1, n + 1):
        u = order[pos]
        # 初始绩效分等于员工编号
        arr[pos] = (u, u)
        ans[u] = u

    seg = SegmentTree(arr)

    # 依次处理 m 轮评优
    for j in range(1, m + 1):
        x = ops[j - 1]
        l, r = dfn[x], out[x]
        _, u = seg.query(1, 1, n, l, r)    # 找出子树中绩效分最低的员工
        new_val = n + j                    # 第 j 轮评优后的新绩效分
        ans[u] = new_val
        seg.update(1, 1, n, dfn[u], (new_val, u))

    return ans[1:]


def main():
    input = sys.stdin.readline
    n, m = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(n - 1)]
    ops = [int(input()) for _ in range(m)]

    res = solve(n, m, edges, ops)
    print(*res)


if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }

    static class Pair {
        int val;
        int node;

        Pair(int val, int node) {
            this.val = val;
            this.node = node;
        }
    }

    static class SegmentTree {
        Pair[] tree;

        SegmentTree(Pair[] arr, int n) {
            tree = new Pair[n * 4];
            build(1, 1, n, arr);
        }

        void build(int idx, int l, int r, Pair[] arr) {
            if (l == r) {
                tree[idx] = arr[l];
                return;
            }
            int mid = (l + r) >> 1;
            build(idx << 1, l, mid, arr);
            build(idx << 1 | 1, mid + 1, r, arr);
            tree[idx] = minPair(tree[idx << 1], tree[idx << 1 | 1]);
        }

        void update(int idx, int l, int r, int pos, Pair val) {
            if (l == r) {
                tree[idx] = val;
                return;
            }
            int mid = (l + r) >> 1;
            if (pos <= mid) {
                update(idx << 1, l, mid, pos, val);
            } else {
                update(idx << 1 | 1, mid + 1, r, pos, val);
            }
            tree[idx] = minPair(tree[idx << 1], tree[idx << 1 | 1]);
        }

        Pair query(int idx, int l, int r, int ql, int qr) {
            if (ql <= l && r <= qr) {
                return tree[idx];
            }
            int mid = (l + r) >> 1;
            Pair res = new Pair(Integer.MAX_VALUE, 0);
            if (ql <= mid) {
                res = minPair(res, query(idx << 1, l, mid, ql, qr));
            }
            if (qr > mid) {
                res = minPair(res, query(idx << 1 | 1, mid + 1, r, ql, qr));
            }
            return res;
        }

        Pair minPair(Pair a, Pair b) {
            if (a.val != b.val) {
                return a.val < b.val ? a : b;
            }
            return a.node < b.node ? a : b;
        }
    }

    static List<Integer>[] graph;
    static int[] dfn, out, order;
    static int timer = 0;

    // 求 DFS 序，把子树映射成连续区间
    static void dfs(int u, int parent) {
        dfn[u] = ++timer;
        order[timer] = u;
        for (int v : graph[u]) {
            if (v != parent) {
                dfs(v, u);
            }
        }
        out[u] = timer;
    }

    static int[] solve(int n, int m, int[][] edges, int[] ops) {
        graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] e : edges) {
            int u = e[0], v = e[1];
            graph[u].add(v);
            graph[v].add(u);
        }

        dfn = new int[n + 1];
        out = new int[n + 1];
        order = new int[n + 1];
        timer = 0;
        dfs(1, 0);

        Pair[] arr = new Pair[n + 1];
        int[] ans = new int[n + 1];

        // 按 DFS 序建立初始数组
        for (int pos = 1; pos <= n; pos++) {
            int u = order[pos];
            arr[pos] = new Pair(u, u);   // 初始绩效分等于员工编号
            ans[u] = u;
        }

        SegmentTree seg = new SegmentTree(arr, n);

        // 依次处理 m 轮评优
        for (int j = 1; j <= m; j++) {
            int x = ops[j];
            Pair p = seg.query(1, 1, n, dfn[x], out[x]);
            int u = p.node;
            int newVal = n + j;           // 第 j 轮评优后的新绩效分
            ans[u] = newVal;
            seg.update(1, 1, n, dfn[u], new Pair(newVal, u));
        }

        return ans;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();

        int[][] edges = new int[n - 1][2];
        for (int i = 0; i < n - 1; i++) {
            edges[i][0] = fs.nextInt();
            edges[i][1] = fs.nextInt();
        }

        int[] ops = new int[m + 1];
        for (int i = 1; i <= m; i++) {
            ops[i] = fs.nextInt();
        }

        int[] res = solve(n, m, edges, ops);

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (i > 1) sb.append(' ');
            sb.append(res[i]);
        }
        System.out.println(sb);
    }
}
