```cpp
#include <bits/stdc++.h>
using namespace std;

struct Node {
    int val, id;
    // 线段树里按绩效分最小比较，绩效分相同时编号小的优先
    bool operator < (const Node& other) const {
        if (val != other.val) return val < other.val;
        return id < other.id;
    }
};

class SegmentTree {
public:
    vector<Node> tree;

    SegmentTree(const vector<Node>& arr, int n) {
        tree.resize(n * 4 + 5);
        build(1, 1, n, arr);
    }

    void build(int idx, int l, int r, const vector<Node>& arr) {
        if (l == r) {
            tree[idx] = arr[l];
            return;
        }
        int mid = (l + r) >> 1;
        build(idx << 1, l, mid, arr);
        build(idx << 1 | 1, mid + 1, r, arr);
        tree[idx] = min(tree[idx << 1], tree[idx << 1 | 1]);
    }

    void update(int idx, int l, int r, int pos, Node val) {
        if (l == r) {
            tree[idx] = val;
            return;
        }
        int mid = (l + r) >> 1;
        if (pos <= mid) update(idx << 1, l, mid, pos, val);
        else update(idx << 1 | 1, mid + 1, r, pos, val);
        tree[idx] = min(tree[idx << 1], tree[idx << 1 | 1]);
    }

    Node query(int idx, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) return tree[idx];
        int mid = (l + r) >> 1;
        Node res = {INT_MAX, 0};
        if (ql <= mid) res = min(res, query(idx << 1, l, mid, ql, qr));
        if (qr > mid) res = min(res, query(idx << 1 | 1, mid + 1, r, ql, qr));
        return res;
    }
};

vector<vector<int>> graph;
vector<int> dfn, outPos, order;
int timer = 0;

// 求 DFS 序，将子树映射为连续区间
void dfs(int u, int parent) {
    dfn[u] = ++timer;
    order[timer] = u;
    for (int v : graph[u]) {
        if (v != parent) {
            dfs(v, u);
        }
    }
    outPos[u] = timer;
}

// 处理题目要求的功能
vector<int> solve(int n, int m, const vector<pair<int, int>>& edges, const vector<int>& ops) {
    graph.assign(n + 1, vector<int>());
    for (auto e : edges) {
        int u = e.first, v = e.second;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    dfn.assign(n + 1, 0);
    outPos.assign(n + 1, 0);
    order.assign(n + 1, 0);
    timer = 0;
    dfs(1, 0);

    vector<Node> arr(n + 1);
    vector<int> ans(n + 1);

    // 按 DFS 序建立初始数组
    for (int pos = 1; pos <= n; pos++) {
        int u = order[pos];
        arr[pos] = {u, u};   // 初始绩效分等于员工编号
        ans[u] = u;
    }

    SegmentTree seg(arr, n);

    // 依次处理 m 轮评优
    for (int j = 1; j <= m; j++) {
        int x = ops[j - 1];
        Node p = seg.query(1, 1, n, dfn[x], outPos[x]);
        int u = p.id;
        int newVal = n + j;   // 第 j 轮评优后的新绩效分
        ans[u] = newVal;
        seg.update(1, 1, n, dfn[u], {newVal, u});
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<pair<int, int>> edges;
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        edges.push_back({u, v});
    }

    vector<int> ops(m);
    for (int i = 0; i < m; i++) {
        cin >> ops[i];
    }

    vector<int> res = solve(n, m, edges, ops);

    for (int i = 1; i <= n; i++) {
        if (i > 1) cout << ' ';
        cout << res[i];
    }
    cout << '\n';

    return 0;
}
